ksl_expected (table_name, row_count) AS (
    VALUES
        ('across_rep_stat', 102),
        ('batch_stat', 0),
        ('control', 0),
        ('experiment', 2),
        ('frequency', 0),
        ('histogram', 0),
        ('model_element', 136),
        ('rv_parameter', 0),
        ('simulation_run', 2),
        ('time_series_response', 0),
        ('within_rep_counter_stat', 780),
        ('within_rep_stat', 2280)
),
present AS (
    SELECT n.nspname AS schema_name, c.relname AS table_name,
           (xpath('/row/h/text()', query_to_xml(format(
               'SELECT md5(COALESCE(string_agg(to_jsonb(t)::text, ''|'' '
               'ORDER BY to_jsonb(t)::text COLLATE "C"), '''')) AS h '
               'FROM %I.%I AS t', n.nspname, c.relname),
               false, true, '')))[1]::text AS fingerprint
    FROM pg_class AS c
    JOIN pg_namespace AS n ON n.oid = c.relnamespace
    WHERE n.nspname IN ('distribution', 'production', 'quality', 'sales')
      AND c.relkind IN ('r', 'v', 'm', 'p')
),
ksl_present AS (
    SELECT c.relname AS table_name,
           (xpath('/row/n/text()', query_to_xml(format(
               'SELECT count(*) AS n FROM ksl_db.%I', c.relname),
               false, true, '')))[1]::text::bigint AS row_count
    FROM pg_class AS c
    JOIN pg_namespace AS n ON n.oid = c.relnamespace
    WHERE n.nspname = 'ksl_db' AND c.relkind = 'r'
),
score AS (
    SELECT e.state,
           count(*) FILTER (WHERE p.fingerprint = e.fingerprint) AS same
    FROM expected AS e
    LEFT JOIN present AS p USING (schema_name, table_name)
    GROUP BY e.state
),
best AS (
    SELECT state FROM score ORDER BY same DESC, state DESC LIMIT 1
),
diff AS (
    SELECT e.schema_name || '.' || e.table_name
           || CASE WHEN p.table_name IS NULL THEN ' (missing)'
                   ELSE ' (changed)' END AS item
    FROM expected AS e
    JOIN best USING (state)
    LEFT JOIN present AS p USING (schema_name, table_name)
    WHERE p.fingerprint IS DISTINCT FROM e.fingerprint
    UNION ALL
    SELECT p.schema_name || '.' || p.table_name || ' (not in the load)'
    FROM present AS p
    WHERE NOT EXISTS (SELECT 1 FROM expected AS e JOIN best USING (state)
                      WHERE e.schema_name = p.schema_name
                        AND e.table_name = p.table_name)
),
ksl_diff AS (
    SELECT count(*) AS differ
    FROM ksl_expected AS e
    FULL JOIN ksl_present AS p USING (table_name)
    WHERE p.row_count IS DISTINCT FROM e.row_count
)
SELECT current_database() AS database,
       CASE WHEN NOT EXISTS (SELECT 1 FROM present) THEN 'nothing: none of the book''s schemas'
            WHEN (SELECT state FROM best) = 'small'
            THEN 'through-q.sql: the small world'
            ELSE 'through-s.sql: the year of history and the warehouse'
       END AS loaded_with,
       CASE WHEN NOT EXISTS (SELECT 1 FROM present)
            THEN 'yes: run code/sql/load/through-q.sql, or through-s.sql in dbconcepts_history'
            WHEN NOT EXISTS (SELECT 1 FROM diff) THEN 'no'
            WHEN (SELECT state FROM best) = 'small'
            THEN 'yes: run code/sql/load/through-q.sql'
            ELSE 'yes: run code/sql/load/through-s.sql'
       END AS reset,
       CASE WHEN NOT EXISTS (SELECT 1 FROM present) THEN 'nothing loaded'
            ELSE COALESCE((SELECT string_agg(item, ', ' ORDER BY item) FROM diff),
                          'nothing')
       END AS changed,
       CASE WHEN NOT EXISTS (SELECT 1 FROM ksl_present) THEN 'not added'
            WHEN (SELECT differ FROM ksl_diff) = 0 THEN 'added, complete'
            ELSE 'added, but incomplete: run code/sql/load/add-k.sql'
       END AS simulation;
